// Native-host/broker integration check, not a live Chromium or RP registration
// test. Use only the disposable profile generated by broker-migration-check.
const assert = require("node:assert/strict");
const crypto = require("node:crypto");
const net = require("node:net");
const path = require("node:path");
const { spawn } = require("node:child_process");

const [profile, record, socket] = process.argv.slice(2);
const availabilityOnly = process.argv.includes("--availability-only");
if (!profile || !record || !socket || !path.basename(profile).startsWith(".sep-check-")) {
  throw new Error("usage: node contrib/check-synthetic-browser.cjs .sep-check-PROFILE RECORD SOCKET");
}
const host = path.resolve(__dirname, "../target/release/keychain-browser-host");
const environment = { ...process.env,
  XDG_CONFIG_HOME: path.join(path.resolve(profile), "config"),
  XDG_STATE_HOME: path.join(path.resolve(profile), "state"),
  XDG_RUNTIME_DIR: path.join(path.resolve(profile), "runtime"),
};
function framed(message) {
  const data = Buffer.from(JSON.stringify(message));
  const header = Buffer.alloc(4);
  header.writeUInt32LE(data.length);
  return Buffer.concat([header, data]);
}
function receive(readable, complete) {
  let data = Buffer.alloc(0);
  readable.on("data", (chunk) => {
    data = Buffer.concat([data, chunk]);
    if (data.length < 4) return;
    const length = data.readUInt32LE(0);
    if (length === 0 || length > 1024 * 1024) throw new Error("invalid reply length");
    if (data.length >= length + 4) complete(JSON.parse(data.subarray(4, length + 4)));
  });
}
async function broker(operation) {
  return new Promise((resolve, reject) => {
    const id = crypto.randomUUID();
    const connection = net.createConnection(socket);
    const timeout = setTimeout(() => { connection.destroy(); reject(new Error("broker probe expired")); }, 10000);
    connection.on("error", (error) => { clearTimeout(timeout); reject(error); });
    receive(connection, (reply) => {
      clearTimeout(timeout); connection.end();
      assert.equal(reply.version, 1); assert.equal(reply.id, id);
      if (reply.error) reject(new Error(reply.error.message)); else resolve(reply.result);
    });
    connection.on("connect", () => connection.write(framed({ version: 1, id, operation })));
  });
}
async function native(message) {
  return new Promise((resolve, reject) => {
    const child = spawn(host, [], { env: environment, stdio: ["pipe", "pipe", "pipe"] });
    let completed = false;
    let errors = "";
    const timeout = setTimeout(() => { child.stdin.destroy(); child.kill(); reject(new Error("native request expired")); }, 80000);
    child.stderr.on("data", (data) => { errors = (errors + data).slice(-4096); });
    child.on("error", (error) => { clearTimeout(timeout); reject(error); });
    child.on("exit", (code) => {
      if (!completed) { clearTimeout(timeout); reject(new Error(`native host exited ${code}: ${errors}`)); }
    });
    receive(child.stdout, (reply) => {
      completed = true; clearTimeout(timeout); child.stdin.end();
      if (!reply.ok) reject(new Error(reply.error?.message || "native request refused")); else resolve(reply.result);
    });
    // Keep stdin open until the reply. EOF intentionally cancels broker work.
    child.stdin.write(framed(message));
  });
}
async function main() {
  const expected = await broker({ kind: "inspect-protected", record });
  assert.equal(expected.verified, true);
  assert.equal(expected.credential.rp_id, "diagnostic.invalid");
  assert.equal(expected.credential.username, "Synthetic migration check");
  const capabilities = await native({ version: 1, action: "capabilities" });
  assert.equal(capabilities.kind, "capabilities");
  assert.equal(capabilities.userVerificationAvailable, true);
  console.log("verified live broker/native-host availability without a fingerprint prompt");
  if (availabilityOnly) return;
  const challenge = crypto.randomBytes(32).toString("base64url");
  const details = JSON.stringify({ challenge, rpId: "diagnostic.invalid", userVerification: "required",
    allowCredentials: [{ type: "public-key", id: expected.credential.credential_id }],
    extensions: { remoteDesktopClientOverride: { origin: "https://diagnostic.invalid", sameOriginWithAncestors: true } },
  });
  const inspection = await native({ version: 1, action: "inspect", requestDetailsJson: details });
  assert.equal(inspection.biometric, true);
  assert.deepEqual(inspection.candidates.map((candidate) => candidate.id), [record]);
  assert.equal(JSON.stringify(inspection).includes(expected.credential.credential_id), false);
  console.log("fresh native-host inspection passed; touch the reader for the synthetic assertion");
  const result = await native({ version: 1, action: "assert", requestDetailsJson: details, passkeyId: record });
  const assertion = JSON.parse(result.responseJson);
  assert.equal(assertion.rawId, expected.credential.credential_id);
  assert.equal(assertion.response.userHandle, expected.credential.user_handle);
  const clientData = Buffer.from(assertion.response.clientDataJSON, "base64url");
  const client = JSON.parse(clientData);
  assert.equal(client.type, "webauthn.get"); assert.equal(client.challenge, challenge);
  assert.equal(client.origin, "https://diagnostic.invalid");
  const auth = Buffer.from(assertion.response.authenticatorData, "base64url");
  assert.equal(auth[32], 0x1d); // UP | UV | BE | BS
  assert.equal(auth.subarray(0, 32).equals(crypto.createHash("sha256").update("diagnostic.invalid").digest()), true);
  const message = Buffer.concat([auth, crypto.createHash("sha256").update(clientData).digest()]);
  const spki = Buffer.concat([Buffer.from("3059301306072a8648ce3d020106082a8648ce3d030107034200", "hex"), Buffer.from(expected.public_sec1, "base64")]);
  const publicKey = crypto.createPublicKey({ key: spki, type: "spki", format: "der" });
  assert.equal(crypto.verify("sha256", message, publicKey, Buffer.from(assertion.response.signature, "base64url")), true);
  console.log("verified fresh-process native-host assertion: unchanged identity, correct flags, valid ES256 signature");
}
main().catch((error) => { console.error(error.message); process.exitCode = 1; });
